const j = ($input.first() && $input.first().json) || {};
const p = String(j.prefijo ?? '');
if (!/^[A-Za-z0-9_-]*$/.test(p)) throw new Error('Prefijo inválido');
return [{ json: { prefijo: p } }];

const prefijo = $('CA86E_Parametros').first().json.prefijo;
const al = $input.all().map((i) => i.json).filter((j) => j.alerta_id);
if (al.length === 0) return [{ json: { hay: false, enviadas: 0, ids: [] } }];
const marca = prefijo ? ' [PRUEBA]' : '';
const critica = al.some((a) => a.severidad === 'S1');
const asunto = `[Cumbre Andina]${marca} ${al.length} ${al.length === 1 ? 'alerta nueva' : 'alertas nuevas'}${critica ? ' (CRITICA)' : ''}`;
const bloques = al.map((a) => `[${a.severidad}] ${a.tipo}
Para: ${a.destinatario}
${a.detalle}
Referencia: ${a.objeto}
`);
const cuerpo = (prefijo ? 'CORREO DE PRUEBA: estas alertas son de una prueba del flujo, no son reales.

' : '') +
  `Alertas pendientes de envío: ${al.length}

` + bloques.join('
') +
  '
Este correo no contiene datos personales. Los datos reales solo los muestra el desenmascarador controlado (8.8).
Proyecto de portafolio con datos ficticios.';
return [{ json: { hay: true, asunto, cuerpo, ids: al.map((a) => Number(a.alerta_id)), enviadas: al.length } }];

const a = $('CA86E_Armar_correo').first().json;
let marcadas = 0; try { marcadas = $('CA86E_Marcar_enviadas').all().filter((i) => i.json.alerta_id).length; } catch (e) { marcadas = 0; }
return [{ json: { estado: a.hay ? 'enviado' : 'sin alertas pendientes', alertas_enviadas: a.hay ? marcadas : 0, asunto: a.asunto || null } }];
